package com.tihai.utils;
import org.junit.jupiter.api.Test;import com.tihai.dubbo.pojo.course.Course;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ExamPageParserTest {
 static String page(String type){return "<input id=courseId value=10><input id=classId value=20><input id=testPaperId value=30><input id=start value=0><ul><li onclick=\"getTheQuestionByStart(0, '0')\">1</li><li onclick=\"getTheQuestionByStart(1, '0')\">2</li></ul><div class=singleQuesId data=91><h3 class=mark_name>1. Example</h3><form id=submitTest><input name=type91 value='"+type+"'><div class=stem_answer><div class=answerBg><span class=num_option data=A>A</span><div class=answer_p>Alpha</div></div><div class=answerBg><span class=num_option_dx data=B>B</span><div class=answer_p>Beta</div></div></div></form><svg class=uiFlag></svg></div>";}
 @Test void readsNestedExamFormAndBothOptionLabels()throws Exception{List<Map<String,Object>> q=ExamPageParser.questions(page("0"));assertEquals(1,q.size());assertEquals("single",q.get(0).get("type"));assertEquals("A. Alpha\nB. Beta",q.get(0).get("options"));assertEquals(false,q.get(0).get("needsVision"));assertEquals(2,ExamPageParser.total(page("0")));ExamPageParser.identity(page("0"),"10","20","30");}
 @Test void imageQuestionRequiresVisionButUiIconDoesNot()throws Exception{assertEquals(true,ExamPageParser.questions(page("0").replace("Example","<img src='data:image/png;base64,AAAA'>")).get(0).get("needsVision"));}
 @Test void unknownTypeMissingCountAndForeignIdentityRejected(){assertThrows(java.io.IOException.class,()->ExamPageParser.questions(page("26")));assertThrows(java.io.IOException.class,()->ExamPageParser.total("<p>unknown</p>"));assertThrows(java.io.IOException.class,()->ExamPageParser.identity(page("0"),"11","20","30"));}
 @Test void courseCatalogEntriesStableAndBoundToCourse()throws Exception{Course c=new Course();c.setCourseId("10");c.setClazzId("20");c.setCpi("40");c.setTitle("Fixture course");String html="<title>课程-考试</title><div class=ulDiv><ul><li><div class=titTxt><p><a title='Fixture exam' onclick=\"goTest('10',30,0,'2099-01-01',50,false,'fixture');\">exam</a></p><strong>待做</strong></div></li></ul></div>";CourseExamCatalog.Entry e=CourseExamCatalog.parse(html,"fixture-account",c).get(0);assertTrue(e.actionable);assertEquals(e.id,CourseExamCatalog.parse(html,"fixture-account",c).get(0).id);assertFalse(e.id.equals(CourseExamCatalog.parse(html,"other-fixture",c).get(0).id));assertThrows(java.io.IOException.class,()->CourseExamCatalog.parse(html.replace("goTest('10'","goTest('11'"),"fixture-account",c));}
 @Test void alertEpisodesDeduplicateResolveAndStartFresh(){SecurityAlertHub hub=new SecurityAlertHub();hub.raise("exams","fixture","Exam","Verification");String id=(String)hub.snapshot().get(0).get("eventId");hub.raise("exams","fixture","Exam","Verification");assertEquals(1,hub.snapshot().size());assertEquals(id,hub.snapshot().get(0).get("eventId"));hub.resolve("exams","fixture");assertTrue(hub.snapshot().isEmpty());hub.raise("exams","fixture","Exam","Verification");assertNotEquals(id,hub.snapshot().get(0).get("eventId"));assertTrue(hub.detect("homework","work","Work","请完成安全验证"));}
}
